class Model {
    private val data = mutableListOf(1, 2)
    fun items(): List<Int> = data      // LEAK: caller can cast & mutate
}

val m = Model()
(m.items() as MutableList<Int>).add(3)   // corrupts internal state

// fixes
fun itemsSafe(): List<Int> = data.toList()               // defensive copy
fun itemsSeq(): Sequence<Int> = data.asSequence()         // hide the store

import kotlinx.collections.immutable.persistentListOf
val immutable: ImmutableList<Int> = persistentListOf(1, 2)  // true immutability

// three eager lists built, 30k element visits
val r = list.map { it * 2 }.filter { it > 5 }.map { it.toString() }

// one reusable list, fewer allocations
val out = ArrayList<String>(list.size)
list.mapTo(out) { it * 2 }

// fused / short-circuiting
val big = list.count { it > 100 }        // no list
val anyBig = list.any { it > 100 }       // stops early

// loop — no Iterator allocation for indices
var total = 0
for (i in list.indices) total += list[i]

val nums = listOf(1, 2, 3)
nums.fold(0) { a, x -> a + x }            // 6 — seed handles empty
nums.reduce { a, x -> a + x }             // 6 — throws on empty
nums.reduceOrNull { a, x -> a + x }       // null-safe

nums.runningFold(0) { a, x -> a + x }     // [0, 1, 3, 6]

// O(n²): acc + x copies the whole list each step
nums.fold(emptyList<Int>()) { acc, x -> acc + x }

// O(n): mutable accumulator
nums.fold(ArrayList<Int>()) { acc, x -> acc.add(x); acc }
